window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8bc0b714b6fadd2b"]={"versions": [{"id": "FIG-8bc0b714b6fadd2b", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzdiagramm) zur Veranschaulichung eines ungültigen partiellen Modells (Invalid Partial Model) im Kontext der AUTOSAR-Modellaufspaltung (Splitable / <code>«atpSplitable»</code>) gemäß dem Generic Structure Template. Das Diagramm demonstriert die Verletzung von Konsistenzregeln beim Zusammenführen bzw. Aufteilen von Teilmodellen über Dateigrenzen hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>:Root</code>: Oberstes Wurzelelement des Modells.\n</li><li><code>package :Package</code>: Untergeordnetes Paket-Element mit Attribut <code>shortName = Supplier</code>.\n</li><li><code>:WithSplitable</code>: Exemplar einer spaltbaren Klasse mit den Attributwerten <code>shortName = centralLock</code> und <code>a = otherText</code>.\n</li><li><code>dataSpec :DataSpec</code>: Untergeordnetes Datenspezifikationselement (hervorgehoben in Gelb).\n</li><li>Assoziationen / Kanten: Gerichtete bzw. hierarchische Baumbeziehungen zwischen den Instanzen, jeweils annotiert mit dem Stereotyp <code>«atpSplitable»</code>.\n</li><li>Rote Kommentar-/Fehlernotiz (Note): Zugeordnet zu <code>:WithSplitable</code>, mit dem Text:\n<ul class=\"fig-list\"><li>„Attribute &quot;a&quot; is repeated but is not part of the splitkey.“\n</li><li>„Attribute &quot;a&quot; and &quot;b&quot; must be together in one file. This is not the case here.“\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Instanzgefüge ohne zeitlichen Ablauf oder Interaktionssequenz. Dargestellt ist der Auswertezeitpunkt eines partiellen ARXML-Modellfragments, bei dem das Vorhandensein bzw. die Belegung von Attributen gegen Modellbildungs- und Serialisierungsregeln der Plattform verstößt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert ein unzulässiges Negativbeispiel für Modell-Splitting:</p>\n<ul class=\"fig-list\"><li>Ein Attribut (<code>a</code>), das nicht Teil des <code>splitkey</code> ist, darf bei mehrfacher Aufspaltung nicht mit abweichenden oder wiederholten Werten ohne Schlüsselqualifikation kollidieren.\n</li><li>Zusammengehörige Attribute (hier <code>a</code> und <code>b</code>) müssen sich gemäß Plattform-Constraint in derselben Datei befinden; das Fehlen von <code>b</code> bzw. die unvollständige Belegung in der vorliegenden Partial-Model-Datei führt zu einem Validierungsfehler im Modell-Parser bzw. Splitter/Merger.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cac06393b0bb543d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzdiagramm) zur Veranschaulichung eines ungültigen partiellen Modells (Invalid Partial Model) im Kontext der AUTOSAR-Modellaufspaltung (Splitable / <code>«atpSplitable»</code>) gemäß dem Generic Structure Template. Das Diagramm demonstriert die Verletzung von Konsistenzregeln beim Zusammenführen bzw. Aufteilen von Teilmodellen über Dateigrenzen hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>:Root</code>: Oberstes Wurzelelement des Modells.\n</li><li><code>package :Package</code>: Untergeordnetes Paket-Element mit Attribut <code>shortName = Supplier</code>.\n</li><li><code>:WithSplitable</code>: Exemplar einer spaltbaren Klasse mit den Attributwerten <code>shortName = centralLock</code> und <code>a = otherText</code>.\n</li><li><code>dataSpec :DataSpec</code>: Untergeordnetes Datenspezifikationselement (hervorgehoben in Gelb).\n</li><li>Assoziationen / Kanten: Gerichtete bzw. hierarchische Baumbeziehungen zwischen den Instanzen, jeweils annotiert mit dem Stereotyp <code>«atpSplitable»</code>.\n</li><li>Rote Kommentar-/Fehlernotiz (Note): Zugeordnet zu <code>:WithSplitable</code>, mit dem Text:\n<ul class=\"fig-list\"><li>„Attribute &quot;a&quot; is repeated but is not part of the splitkey.“\n</li><li>„Attribute &quot;a&quot; and &quot;b&quot; must be together in one file. This is not the case here.“\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Instanzgefüge ohne zeitlichen Ablauf oder Interaktionssequenz. Dargestellt ist der Auswertezeitpunkt eines partiellen ARXML-Modellfragments, bei dem das Vorhandensein bzw. die Belegung von Attributen gegen Modellbildungs- und Serialisierungsregeln der Plattform verstößt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert ein unzulässiges Negativbeispiel für Modell-Splitting:</p>\n<ul class=\"fig-list\"><li>Ein Attribut (<code>a</code>), das nicht Teil des <code>splitkey</code> ist, darf bei mehrfacher Aufspaltung nicht mit abweichenden oder wiederholten Werten ohne Schlüsselqualifikation kollidieren.\n</li><li>Zusammengehörige Attribute (hier <code>a</code> und <code>b</code>) müssen sich gemäß Plattform-Constraint in derselben Datei befinden; das Fehlen von <code>b</code> bzw. die unvollständige Belegung in der vorliegenden Partial-Model-Datei führt zu einem Validierungsfehler im Modell-Parser bzw. Splitter/Merger.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b5f963c731e8ebb0", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzdiagramm) zur Veranschaulichung eines ungültigen partiellen Modells (Invalid Partial Model) im Kontext der AUTOSAR-Modellaufspaltung (Splitable / <code>«atpSplitable»</code>) gemäß dem Generic Structure Template. Das Diagramm demonstriert die Verletzung von Konsistenzregeln beim Zusammenführen bzw. Aufteilen von Teilmodellen über Dateigrenzen hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>:Root</code>: Oberstes Wurzelelement des Modells.\n</li><li><code>package :Package</code>: Untergeordnetes Paket-Element mit Attribut <code>shortName = Supplier</code>.\n</li><li><code>:WithSplitable</code>: Exemplar einer spaltbaren Klasse mit den Attributwerten <code>shortName = centralLock</code> und <code>a = otherText</code>.\n</li><li><code>dataSpec :DataSpec</code>: Untergeordnetes Datenspezifikationselement (hervorgehoben in Gelb).\n</li><li>Assoziationen / Kanten: Gerichtete bzw. hierarchische Baumbeziehungen zwischen den Instanzen, jeweils annotiert mit dem Stereotyp <code>«atpSplitable»</code>.\n</li><li>Rote Kommentar-/Fehlernotiz (Note): Zugeordnet zu <code>:WithSplitable</code>, mit dem Text:\n<ul class=\"fig-list\"><li>„Attribute &quot;a&quot; is repeated but is not part of the splitkey.“\n</li><li>„Attribute &quot;a&quot; and &quot;b&quot; must be together in one file. This is not the case here.“\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Instanzgefüge ohne zeitlichen Ablauf oder Interaktionssequenz. Dargestellt ist der Auswertezeitpunkt eines partiellen ARXML-Modellfragments, bei dem das Vorhandensein bzw. die Belegung von Attributen gegen Modellbildungs- und Serialisierungsregeln der Plattform verstößt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert ein unzulässiges Negativbeispiel für Modell-Splitting:</p>\n<ul class=\"fig-list\"><li>Ein Attribut (<code>a</code>), das nicht Teil des <code>splitkey</code> ist, darf bei mehrfacher Aufspaltung nicht mit abweichenden oder wiederholten Werten ohne Schlüsselqualifikation kollidieren.\n</li><li>Zusammengehörige Attribute (hier <code>a</code> und <code>b</code>) müssen sich gemäß Plattform-Constraint in derselben Datei befinden; das Fehlen von <code>b</code> bzw. die unvollständige Belegung in der vorliegenden Partial-Model-Datei führt zu einem Validierungsfehler im Modell-Parser bzw. Splitter/Merger.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8bc0b714b6fadd2b", "to": "FIG-cac06393b0bb543d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Bei den UML-Objekten <code>package :Package</code> und <code>:WithSplitable</code> wurde eine horizontale Trennlinie zwischen dem Kopfbereich (Instanz-/Klassenname) und dem Attributbereich eingefügt.\n</li></ul>"}, {"from": "FIG-cac06393b0bb543d", "to": "FIG-b5f963c731e8ebb0", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
